1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.util.Collection;
5	import java.util.Locale;
6	import java.util.UUID;
7	
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.repository.OwnerRepository;
10	
11	/**
12	 * The single definition of an owner "household": owners sharing the same last name and
13	 * address. The last name is compared case-insensitively with runs of whitespace collapsed
14	 * to a single space; the address is compared in its canonical {@link AddressNormalizer}
15	 * form, so both membership and the identifier use the same normalized address that is
16	 * stored and returned. Provides the membership test and the stable identifier shared by
17	 * the household.
18	 *
19	 * <p>The identifier is derived deterministically from the normalized last name and
20	 * address, so every owner in the same household resolves to the same value regardless of
21	 * creation order.
22	 *
23	 * @see EnsureUniqueHousehold rejects a duplicate household unless the request opts in.
24	 * @see AssignHousehold assigns the shared identifier to the joining owners.
25	 */
26	final class Household {
27	
28	    private Household() {
29	    }
30	
31	    /** Whether {@code owner} belongs to the household keyed by {@code lastName} and {@code address}. */
32	    static boolean matches(Owner owner, String lastName, String address) {
33	        return normalizeName(lastName).equals(normalizeName(owner.getLastName()))
34	                && AddressNormalizer.normalize(address).equals(AddressNormalizer.normalize(owner.getAddress()));
35	    }
36	
37	    /** The number of owners in {@code owner}'s household — those sharing its {@code householdId} — or
38	     *  1 when it belongs to no shared household (its {@code householdId} is unset). */
39	    static int size(Owner owner, OwnerRepository ownerRepository) {
40	        return size(owner, ownerRepository.findAll());
41	    }
42	
43	    /** As {@link #size(Owner, OwnerRepository)} but counting within an already-loaded set of owners,
44	     *  so a whole page can be sized from a single query. */
45	    static int size(Owner owner, Collection<Owner> owners) {
46	        String householdId = owner.getHouseholdId();
47	        if (householdId == null) {
48	            return 1;
49	        }
50	        int count = 0;
51	        for (Owner other : owners) {
52	            if (householdId.equals(other.getHouseholdId())) {
53	                count++;
54	            }
55	        }
56	        return count;
57	    }
58	
59	    /** The stable identifier shared by every owner in the household keyed by {@code lastName} and {@code address}. */
60	    static String id(String lastName, String address) {
61	        String key = normalizeName(lastName) + "\n" + AddressNormalizer.normalize(address);
62	        return UUID.nameUUIDFromBytes(key.getBytes(StandardCharsets.UTF_8)).toString();
63	    }
64	
65	    /** A last name trimmed and lower-cased, with internal whitespace runs collapsed to a single space. */
66	    private static String normalizeName(String value) {
67	        return value == null ? "" : value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
68	    }
69	}
